  ('רמת גן', 'אזור הבילוים', 32.060109, 34.827326, false, 49, '[[32.066885,34.821213],[32.0645,34.820383],[32.064446,34.820414],[32.064005,34.823545],[32.063487,34.827657],[32.063435,34.828427],[32.063454,34.828471],[32.0635,34.828479],[32.061872,34.83026],[32.060458,34.835038],[32.056751,34.83297],[32.052307,34.82981],[32.0565,34.827066],[32.057791,34.827721],[32.058714,34.828071],[32.058794,34.82789],[32.059504,34.825432],[32.059703,34.82457],[32.059823,34.823672],[32.059821,34.822074],[32.059781,34.821566],[32.059976,34.821323],[32.063219,34.819819],[32.067328,34.818638],[32.067344,34.819305],[32.066885,34.821213]]'::jsonb),
